<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Services\AuthorizationService;use App\Services\IntegrationEventOperationsService;
final class IntegrationEventController
{private AuthorizationService $auth;private IntegrationEventOperationsService $events;public function __construct(){$this->auth=new AuthorizationService();$this->events=new IntegrationEventOperationsService();}public function index():void{$this->auth->requireTenantPermission('administration.integration_events.view');$data=$this->events->listing(['status'=>trim((string)($_GET['status']??'')),'event_type'=>trim((string)($_GET['event_type']??'')),'date_from'=>trim((string)($_GET['date_from']??'')),'date_to'=>trim((string)($_GET['date_to']??''))]);\view('layouts.app',['applicationName'=>\config('name','OfficeApp ERP'),'pageTitle'=>'Integration Events','pageDescription'=>'Tenant-scoped event delivery, failures and production worker health.','contentView'=>'administration.integration-events','user'=>$_SESSION['auth'],'notice'=>\getFlash('integration_event_notice'),'error'=>\getFlash('integration_event_error')]+$data);}public function retry(string $id):void{$this->auth->requireTenantPermission('administration.integration_events.retry');if(!\verifyCsrfToken(\postString('_token'))){\flash('integration_event_error','The form session expired.');\redirect('/administration/integration-events');}try{$this->events->retry($id,(int)($_SESSION['auth']['user_id']??0));\flash('integration_event_notice','Failed event was safely requeued.');}catch(\Throwable $e){\flash('integration_event_error',$e->getMessage());}\redirect('/administration/integration-events');}}
